// Source of truth for supabase/seed.sql (generated by scripts/gen-seed.mjs).
// Prices are EXAMPLES in whole ARS pesos, editable from the admin. Real business data is left as [COMPLETAR].

export interface SeedCategory {
  key: string
  name: string
  description: string
}
export interface SeedGroup {
  key: string
  name: string
  min: number
  max: number
  required: boolean
  options: [string, number][]
}
export interface SeedProduct {
  cat: string
  name: string
  price: number
  spicy: number
  tags: string[]
  image: string
  unit: string
  desc: string
  groups: string[]
  type?: 'single' | 'combo'
  combo?: [string, number][]
}
export interface SeedZone {
  name: string
  neighborhoods: string[]
  fee: number
  minOrder: number
}
export interface SeedCoupon {
  code: string | null
  label: string
  kind: 'percent' | 'fixed' | 'two_for_one'
  value: number
  scope: 'all' | 'category' | 'products'
  scopeCat?: string
  weekdays: number[]
  maxPerPhone?: number
  autoApply: boolean
}

